namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId = 1;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.Add(new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-30)));
        _notifications.Add(new(NextId(), "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-15)));
        _notifications.Add(new(NextId(), "New comment on your post.", DateTime.UtcNow.AddMinutes(-5)));
    }

    /// <summary>Returns all notifications available at this moment.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called by the background generator so the polling loop has something to find.
    /// </summary>
    public void AddRandom()
    {
        string[] samples =
        [
            "Server deployment completed.",
            "A user mentioned you in a comment.",
            "Weekly report is ready.",
            "Disk usage alert on server-2.",
            "New team member joined the project.",
            "Build #1042 succeeded.",
            "Scheduled maintenance tonight at 11 PM.",
        ];

        var msg = samples[Random.Shared.Next(samples.Length)];

        lock (_lock)
        {
            _notifications.Add(new(NextId(), msg, DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

